import * as React from "react";
import { cx } from "./cx";

export interface CrumbBarItem {
  label: React.ReactNode;
  href?: string;
}

export interface CrumbBarProps extends React.HTMLAttributes<HTMLElement> {
  trail: CrumbBarItem[];
  /** Pixels of scroll before the bar solidifies and the crumbs fade in. */
  threshold?: number;
  /** Root crumb, held in the TOC column from 900px. */
  root?: CrumbBarItem;
  /** Abbreviated root shown on phones in place of the full label. */
  rootShort?: React.ReactNode;
}

/**
 * The fixed top bar of the house chrome. Transparent at rest; once the
 * page cover scrolls away it gains the paper background and its bottom
 * hairline, and the breadcrumbs fade in.
 */
export function CrumbBar({ trail, threshold = 110, root, rootShort, className, ...props }: CrumbBarProps) {
  const [scrolled, setScrolled] = React.useState(false);

  React.useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > threshold);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, [threshold]);

  return (
    <nav
      className={cx("rs-crumb-bar", scrolled && "rs-crumb-bar-scrolled", className)}
      aria-label="Breadcrumbs"
      {...props}
    >
      <div className="rs-crumb-bar-inner">
        {root &&
          (root.href ? (
            <a className="rs-crumb-root" href={root.href}>
              {rootShort ? <span className="rs-crumb-root-full">{root.label}</span> : root.label}
              {rootShort && <span className="rs-crumb-root-short">{rootShort}</span>}
            </a>
          ) : (
            <span className="rs-crumb-root">
              {rootShort ? <span className="rs-crumb-root-full">{root.label}</span> : root.label}
              {rootShort && <span className="rs-crumb-root-short">{rootShort}</span>}
            </span>
          ))}
        <p className="rs-crumbs">
          {trail.map((crumb, index) => {
            const last = index === trail.length - 1;
            return (
              <React.Fragment key={index}>
                {index > 0 && (
                  <span className="rs-crumbs-sep" aria-hidden="true">
                    /
                  </span>
                )}
                {last ? (
                  <span className="rs-crumbs-here">{crumb.label}</span>
                ) : crumb.href ? (
                  <a className="rs-crumbs-link" href={crumb.href}>
                    {crumb.label}
                  </a>
                ) : (
                  <span>{crumb.label}</span>
                )}
              </React.Fragment>
            );
          })}
        </p>
      </div>
    </nav>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Crumb bar: fixed top bar in the house chrome ──
   Transparent at rest; once the page cover scrolls away it gains the
   paper background and its bottom hairline, and the breadcrumbs
   appear. From 900px the root crumb holds the TOC column; the inner row
   starts one module in at the 1024px rail. */
.rs-crumb-bar{position:fixed;top:0;left:0;right:0;z-index:160;display:flex;align-items:center;height:72px;font-size:13px;font-weight:500;letter-spacing:-.01em;line-height:1.3;background:none;border-bottom:1px solid transparent;transition:var(--transition)}
.rs-crumb-bar-scrolled{background:var(--bg);border-bottom-color:var(--divider)}
.rs-crumb-bar-inner{display:flex;align-items:center;gap:20px;width:100%;min-width:0;padding:0 56px 0 76px}
.rs-crumb-bar .rs-crumbs{margin:0;min-width:0;overflow:hidden;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity var(--duration) var(--ease)}
.rs-crumb-bar-scrolled .rs-crumbs{opacity:1;pointer-events:auto}
.rs-crumb-bar a{color:inherit;text-decoration:none}
.rs-crumb-root{flex-shrink:0;color:var(--text);text-decoration:none;transition:color var(--duration-snap) var(--ease)}
.rs-crumb-bar .rs-crumbs-here{overflow:hidden;text-overflow:ellipsis}
/* Root abbreviation: the short name shows only on phones, leaving the
   path room to dock and ellipsize. */
.rs-crumb-root-short{display:none}
@media(min-width:900px){.rs-crumb-root{width:184px}}
@media(min-width:1024px){.rs-crumb-bar-inner{margin-left:204px;padding-left:var(--pad)}}
@media(max-width:899px){.rs-crumb-bar-inner{gap:6px}.rs-crumb-root{font-weight:600}}
@media(max-width:640px){
  .rs-crumb-bar{height:64px;font-size:12px}
  .rs-crumb-bar-inner{padding:0 50px 0 62px}
  .rs-crumb-root-full{display:none}
  .rs-crumb-root-short{display:inline}
}
@media(max-width:480px){.rs-crumb-bar-inner{padding:0 56px 0 74px}}
